/**
 * A plain AbortController convenience: mints a raw controller and returns its signal plus a bound
 * `abort`. No CancelError wiring, this is the native-shaped helper. For a signal that cancels a
 * CancelablePromise with a CancelError, use `createCancelSignal` from `@cancjs/promise`.
 */
export declare function createAbortSignal(): {
    signal: AbortSignal;
    abort: (reason?: unknown) => void;
};
/**
 * Inverse interop: derive an AbortSignal that fires when `promise` cancels. Lets a cancelable
 * operation drive a downstream API that only speaks AbortSignal (fetch, an AbortSignal.any
 * composition, etc). A fulfilled promise never aborts the signal.
 *
 * For a canc promise this fires on cancelation only, not on an ordinary rejection: the signal is
 * wired through `handleCancel`, not `.then`, so taking a signal off a promise never registers as
 * a consumer and never suppresses that promise's own bubble-cancel propagation. A plain thenable
 * has no cancelation to distinguish from a rejection, so it keeps the old any-rejection behavior.
 */
export declare function toAbortSignal(promise: PromiseLike<unknown>): AbortSignal;
/**
 * p-signal-shaped: race `promiseOrFn` against `signal` aborting. A function input receives the
 * signal so it can wire native cancellation, then its result is raced. When `signal` is `undefined`
 * the value passes through unraced (optional-cancellation signatures: callers thread an optional
 * signal without branching). Aborting rejects with the signal's abort reason (a DOMException
 * AbortError); an already-aborted signal rejects immediately.
 */
export declare function withSignal<T>(signal: AbortSignal | undefined, promiseOrFn: ((signal?: AbortSignal) => T | PromiseLike<T>) | T | PromiseLike<T>): Promise<T>;
